import { NextResponse } from "next/server";
import { walletService } from "@/services/auth/walletService";
import { createClient } from "@/utils/supabase/server";

export async function POST(request: Request) {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  try {
    const { amount, method, accountId } = await request.json();
    if (!amount || !method || !accountId) {
      return NextResponse.json({ error: "Amount, method, and account ID are required" }, { status: 400 });
    }

    const res = await walletService.requestWithdrawal(user.id, amount, method, accountId);
    if (res.error) {
      return NextResponse.json({ error: res.error }, { status: 400 });
    }

    return NextResponse.json({ success: true });
  } catch (err: unknown) {
    const errorMessage = err instanceof Error ? err.message : "Unknown error occurred";
    return NextResponse.json({ error: errorMessage }, { status: 500 });
  }
}
